package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.math.*;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.*;
import org.apache.commons.io.output.StringIOWriter;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CSVPrinter#println()
 */
public class CSVPrinter_println_TriageGen1Test {

    @Test
    public void testPrintlnAppendsRecordSeparator() throws IOException {
        // Arrange
        StringIOWriter out = new StringIOWriter();
        CSVFormat format = CSVFormat.DEFAULT; // Default separator is \r\n or \n depending on OS/version
        CSVPrinter printer = new CSVPrinter(out, format);
        String expectedSeparator = format.getRecordSeparator();

        // Act
        printer.println();

        // Assert
        Assert.assertEquals("The println method should append the record separator to the output.",
                expectedSeparator, out.toString());
    }

    @Test
    public void testPrintlnMultipleCalls() throws IOException {
        // Arrange
        StringIOWriter out = new StringIOWriter();
        CSVFormat format = CSVFormat.DEFAULT;
        CSVPrinter printer = new CSVPrinter(out, format);
        String sep = format.getRecordSeparator();

        // Act
        printer.println();
        printer.println();

        // Assert
        Assert.assertEquals("Multiple calls to println should append the separator multiple times.",
                sep + sep, out.toString());
    }

    @Test
    public void testPrintlnAfterPrint() throws IOException {
        // Arrange
        StringIOWriter out = new StringIOWriter();
        CSVFormat format = CSVFormat.DEFAULT;
        CSVPrinter printer = new CSVPrinter(out, format);
        String sep = format.getRecordSeparator();

        // Act
        printer.print("Hello");
        printer.println();

        // Assert
        Assert.assertEquals("println should append the separator after existing content.",
                "Hello" + sep, out.toString());
    }

    @Test(expected = IOException.class)
    public void testPrintlnThrowsIOExceptionOnFailure() throws IOException {
        // Arrange
        // A custom Appendable that always throws IOException
        Appendable throwingAppendable = new Appendable() {
            @Override
            public Appendable append(CharSequence csq) throws IOException {
                throw new IOException("Simulated IO failure");
            }

            @Override
            public Appendable append(CharSequence csq, int start, int end) throws IOException {
                throw new IOException("Simulated IO failure");
            }

            @Override
            public Appendable append(char c) throws IOException {
                throw new IOException("Simulated IO failure");
            }
        };

        CSVPrinter printer = new CSVPrinter(throwingAppendable, CSVFormat.DEFAULT);

        // Act
        printer.println();

        // Assert handled by expected exception
    }
}
